// variável
const combinado = 30;
const entrega = 18;

// função
function adicional(combinado, entrega) {
  const valor = combinado - entrega;
  // condição
  if (valor < 0) return 0;
  return valor;
}

console.log(adicional(combinado, entrega)); // 12

